"""Finray_design_auto generates the CAD and export .STEP files for the fin-ray finger, base, and combined assembly (for multimateral printing)
using randomised design parameters generated by final.py""" 


import cadquery as cq
import math
import numpy as np
import os

# Set default units for angles to degrees
np.set_printoptions(precision=3, suppress=True, formatter={'all': lambda x: f'{x}°'})

# Get current working directory
path = os.getcwd()

def fin_design(input, batch_name, design_name):
    # input is the design parameters/dimensions of the fin-ray randomly generated by final.py
    # batch_name and design_name are used to create labels on gripper base
    
    l_h = input[0]
    l_w = input[1]
    l_t=input[2]
    l_tip=input[3]
    l_hh=l_h-l_tip
    
    t_back = input[4]
    t_flex = input[5]
    t_rib = input[6]
    n = np.rint(input[7]).astype(int) # Makes sure that number of ribs are an integer
    theta_rib =input[8]

    # Triangle base side angle
    theta = math.degrees(math.atan2(l_h, l_w/2)) 
    # Half triangle tip angle+
    theta_l = 90 - theta
    theta_tip = 2*theta_l 

    a = np.sin(np.deg2rad(theta))
    b=np.cos(np.deg2rad(theta_rib))
    c=np.sin(np.deg2rad(theta_rib))

    # Calculate gap between neighbouring ribs
    l_gap=(l_hh/b-n*t_rib)/(n+1)

    l_base = l_w*np.tan(np.deg2rad(theta_l))

    # Create a new CadQuery Workplane object
    xy_plane = cq.Workplane("XY")

    # Define the vertices of the external triangle, with base center as the origin
    p1 = cq.Vector(l_w/2, 0, 0) #side vertice
    p2 = cq.Vector(-l_w/2,0, 0) #side vertice
    p3 = cq.Vector(0, l_h, 0) #tip vertice

    # Define the vertices of the internal trapezoid
    p4 = cq.Vector(l_w/2-t_flex/a, 0, 0)
    p5 = cq.Vector(l_w/2-t_flex/a-(l_h-l_tip)/(l_h/l_w*2), l_h-l_tip, 0)
    p6 = cq.Vector(-(l_w/2-t_back/a-(l_h-l_tip)/(l_h/l_w*2)), l_h-l_tip, 0)
    p7 = cq.Vector(-(l_w/2-t_back/a), 0, 0)

    # Step1: Create the external triangle and extrude 
    # With the defined vertices (p1,p2, and p3) create a sketch and extrude by defined thickness (l_t) with 2.5mm fillets
    sketch1 = (
        xy_plane
        .moveTo(p1.x, p1.y)
        .lineTo(p2.x, p2.y)
        .lineTo(p3.x, p3.y)
        .close()
        )

    triangle1 = sketch1.extrude(l_t).edges(">Y").fillet(2.5)

    # Step2: Extrude cut the internal triangle
    # With the defined vertices (p4, p5, p6, and p7) create sketch and extrude cut by the same thickness (l_t)

    sketch2= (
        xy_plane
        .moveTo(p4.x, p4.y)
        .lineTo(p5.x, p5.y)
        .lineTo(p6.x, p6.y)
        .lineTo(p7.x, p7.y)
        .close()
        )

    triangle2 = sketch2.extrude(l_t)

    # Remove internal trapezoid (triangle)
    triangle3 = triangle1.cut(triangle2)


    # Step3 Add base mount at bottom of fin-ray
    t_base = 8 # Add thickness at base
    p8= cq.Vector(-l_w/2,-t_base, 0)
    p9 = cq.Vector(l_w/2, -t_base, 0)


    # Create a rectangular extrusion at the base by the same thickness (l_t)
    #rec = xy_plane.moveTo(p1.x, p1.y).lineTo(p2.x, p2.y).lineTo(p8.x, p8.y).lineTo(p9.x, p9.y).close().extrude(l_t).edges("<Y").fillet(2.5)
    rec = xy_plane.moveTo(p1.x, p1.y).lineTo(p2.x, p2.y).lineTo(p8.x, p8.y).lineTo(p9.x, p9.y).close().extrude(l_t).edges("<Y")

    # Define vertices of base cavity
    p10 = cq.Vector(-13, -2,0)
    p11=cq.Vector(-13, -5.2,0)
    p12=cq.Vector(-8, -5.2, 0)
    p13=cq.Vector(-8,-t_base,0)
    p14=cq.Vector(8,-t_base,0)
    p15=cq.Vector(8, -5.2,0)
    p16=cq.Vector(13, -5.2, 0)
    p17=cq.Vector(13, -2,0)

    cavity = xy_plane.moveTo(p10.x, p10.y).lineTo(p11.x, p11.y).lineTo(p12.x, p12.y).lineTo(p13.x, p13.y).lineTo(p14.x, p14.y) \
                        .lineTo(p15.x, p15.y).lineTo(p16.x, p16.y).lineTo(p17.x, p17.y).close().extrude(l_t) 

    # Subtract defined cavity extrusion from rectangular extrusion               
    rec1 = rec.cut(cavity)

    # Combine fin-ray extruded triangle with extruded base
    fin = triangle3.add(rec1)

    # Define vertices for a triangle below base
    p18= p8 
    p19= p9 
    p20=cq.Vector(l_w/2, -t_base-l_base ,0)

    # Create triangle extrusion at bottom of base, to angle fin-ray
    cavity2 = xy_plane.moveTo(p18.x, p18.y).lineTo(p19.x, p19.y).lineTo(p20.x, p20.y).close().extrude(l_t)

    p199=cq.Vector(l_w/2+(l_w/np.cos(np.deg2rad(theta_l))-l_w), -t_base,0)
    p21 =  cq.Vector(l_w/2, -18,0)
    p22 =  cq.Vector(l_w/2-8, -26,0)
    p23 =  cq.Vector(-l_w/2+8, -26,0)
    p24 =  cq.Vector(-l_w/2, -18,0)

    # Add trapezoid below triangle extrusion 
    cavity3 = xy_plane.moveTo(p18.x, p18.y).lineTo(p199.x, p199.y).lineTo(p20.x, p20.y).lineTo(p21.x, p21.y).lineTo(p22.x, p22.y).lineTo(p23.x, p23.y).lineTo(p24.x, p24.y).close() \
                        .extrude(l_t) \
                        .faces(">Z").workplane().pushPoints([(-l_w/2+6, -18), (-l_w/2+22, -18)]) \
                        .circle(1.6).cutThruAll()
                        
                        
    # Define a slot that needs to be cut from the base
    slot_width = 15 # do not change
    cavity4 = cq.Workplane("XY").transformed(offset=(0, 0, l_t/2-7.5)).moveTo(p18.x, p18.y-5).lineTo(p199.x, p199.y).lineTo(p20.x, p20.y).lineTo(p21.x, p21.y) \
                        .lineTo(p22.x, p22.y) \
                        .lineTo(p23.x, p23.y).lineTo(p24.x, p24.y).close() \
                        .extrude(slot_width) \


    cavity5 = cavity3.cut(cavity4) \
                    .rotate((-l_w/2, -t_base,0), (-l_w/2, -t_base,l_t), angleDegrees=-(90-theta))

    cavity6 = cavity5.union(cavity).union(cavity2)


    # Step4 Add all the ribs
    # Add rib 1 and make sure the rib does not intersect bottom plane 

    # Internal flexible surface vector (p5-p4)
    bottom_length = l_w-t_flex/a-t_back/a #distance between p4 and p7
    theta1 = 180-abs(theta_rib)-abs(theta)

    # Use sine theorem to calculate the intial gap distance
    l_gap_initial = np.sin(np.deg2rad(abs(theta_rib)))/np.sin(np.deg2rad(theta1))*bottom_length

    # Calculate length of internal triangle of fin-ray (assumes both sides are equal in length)
    int_length= np.sqrt(((l_h-l_tip)/(l_h/l_w*2))**2 + (l_h-l_tip)**2)
    scale = l_gap_initial/int_length

    # Use sine theorem to calculate multiplier (needed to make sure rib thickness is uniform)
    theta_int = theta-abs(theta_rib)
    multiplier = np.sin(np.deg2rad(180-theta_tip-(theta_int)))/np.sin(np.deg2rad(theta_int))

    # Calculate distance between ribs based on number of ribs N
    rib_gap = ((1-scale)*int_length-n*t_rib)/(n+1)
        
    # First rib corner vertice  
    p25 = p7+(p6-p7)*scale
        

    # UNCOMMENT BOTH LINES TO ADD TRIANGLE AREA       
    #rib1 = xy_plane.moveTo(p7.x, p7.y).lineTo(p4.x, p4.y).lineTo(p25.x, p25.y).close().extrude(l_t)
    #fin= fin.union(rib1)


    if theta_rib>=0:

        # Extrude ribs one-by-one
        for ribn in range(1,n+1):
            # Flex side rib vertice pair
            pp1 =  p4+(p5-p4)*((l_gap_initial + rib_gap*ribn + t_rib*(ribn-1))/int_length)
            pp2 =  p4+(p5-p4)*((l_gap_initial + rib_gap*ribn + t_rib*ribn)/int_length)

            # Back side rib vertice pair
            pp3 = p7+(p6-p7)*((rib_gap*ribn + t_rib*ribn) *multiplier/int_length)
            pp4 = p7+(p6-p7)*((rib_gap*ribn + t_rib*(ribn-1)) *multiplier/int_length)



            rib2 = xy_plane.moveTo(pp1.x, pp1.y).lineTo(pp2.x, pp2.y).lineTo(pp3.x, pp3.y).lineTo(pp4.x, pp4.y).close().extrude(l_t)
            fin= fin.union(rib2)

    else:
        # If rib angle is negative, this code runs

        # Extrude ribs one-by-one
        for ribn in range(1,n+1):
            # Back side rib vertice pair
            pp1 =  p7+(p6-p7)*((l_gap_initial + rib_gap*ribn + t_rib*(ribn-1))/int_length)
            pp2 =  p7+(p6-p7)*((l_gap_initial + rib_gap*ribn + t_rib*ribn)/int_length)

            # Flex side rib vertice pair
            pp3 = p4+(p5-p4)*((rib_gap*ribn + t_rib*ribn) *multiplier/int_length)
            pp4 = p4+(p5-p4)*((rib_gap*ribn + t_rib*(ribn-1)) *multiplier/int_length)


            rib2 = xy_plane.moveTo(pp1.x, pp1.y).lineTo(pp2.x, pp2.y).lineTo(pp3.x, pp3.y).lineTo(pp4.x, pp4.y).close().extrude(l_t)
            fin= fin.union(rib2)
    
    
    # Step5 Define a text string and add it to the model using defined batch_name in final.py
    text_string = batch_name+str(design_name)
    cavity6 =cavity6.faces(">Z").center(0, -10).workplane().text(text_string, 5, -1,cut=True, halign = "center", valign = "top" )

    # Step6 Rotate in correct orientation for simulation
    fin_soft= fin.translate((l_w/2,0,0)).rotate((0,0,0), (0,1,0), angleDegrees=90).rotate((0,0,0), (1,0,0), angleDegrees=theta_l).translate((-l_t/2,0,0))
    base = cavity6.translate((l_w/2,0,0)).rotate((0,0,0), (0,1,0), angleDegrees=90).rotate((0,0,0), (1,0,0), angleDegrees=theta_l).translate((-l_t/2,0,0))
    
    
    # Step7 Export CAD
    base_path = os.getcwd()
    # Path to save fin and base .STEP files for simulation
    subfolder_mesh = "data/mesh"
    # Path to save whole finger .STEP files for printing
    subfolder_print = "data/fingers"

    base_path_print = os.path.join(base_path, subfolder_print)
    base_path_mesh = os.path.join(base_path, subfolder_mesh)

    path_soft = os.path.join(base_path_mesh, str(design_name) + "_soft.step")
    path_basic = os.path.join(base_path_mesh, str(design_name) + "_basic.step")
    path_whole = os.path.join(base_path_print, str(design_name) + "_whole.step")

    # Export fin and base seperately
    cq.exporters.export(fin_soft, path_soft)
    cq.exporters.export(base, path_basic)

    # Combine fin and base into a whole finger and export
    fin_whole = fin_soft.add(base)
    cq.exporters.export(fin_whole, path_whole)

    return path_soft, path_basic, path_whole
